#!/usr/bin/env python3
"""Independent count-transfer / valuation-gate check (read-only; writes /tmp only)."""
import hashlib, json, os, platform, resource, subprocess, sys, tempfile, time
from datetime import datetime, timezone
MASKS = (0, 3, 11, 12, 15)
PHASES = ("p", "u")
TIME_BUDGET = 120.0
OUT = "/tmp/count_transfer_result.json"
def forward_generator(name, state):
    stepped = state ^ ((state << 1) | (state << 2))
    if name == "t":
        return stepped
    if name == "u":
        return stepped ^ 1
    return stepped ^ 1 ^ (2 if state & 1 == 0 else 0)
def children(state):
    return tuple(sorted({forward_generator(n, state) for n in "tup"}))
def oracle_children(state):
    width = state.bit_length() + 2
    bits = [(state >> j) & 1 for j in range(width)]
    tout = 0
    for j in range(width):
        lo1 = bits[j-1] if j >= 1 else 0
        lo2 = bits[j-2] if j >= 2 else 0
        if bits[j] ^ (lo1 | lo2):
            tout |= 1 << j
    uout = tout ^ 1
    p0 = (tout & 1) ^ 1
    p1 = ((tout >> 1) & 1) ^ (1 if state & 1 == 0 else 0)
    return tuple(sorted({tout, uout, (tout & ~3) ^ p0 ^ (p1 << 1)}))
def build(phase, kmax, fn):
    lv = [set(), {3 if phase == "p" else 1}]
    for _ in range(2, kmax + 1):
        lv.append({c for s in lv[-1] for c in fn(s)})
    return lv
def fiber(lv, c, q):
    m = sum(1 << d for d in range(4) if 4 * q + d in lv[c + 1])
    assert m in MASKS
    return m
def masks_seq(lv, c, x, L):
    out = []
    for s in range(L):
        q = x >> 2
        out.append(fiber(lv, c - 1 - s, q))
        x = q
    return tuple(out)
def belief(lv, c, x, L):
    mod = 4 ** L
    res = x % mod
    cur = masks_seq(lv, c, x, L)
    out = {}
    for sh in lv[c - 1]:
        if sh % mod != res:
            continue
        sm = masks_seq(lv, c - 1, sh, L)
        if len(cur) == len(sm) and all(not (a & ~b) for a, b in zip(cur, sm)):
            out[sh] = sum(m != 15 for m in sm)
    return out
def belief_rec(lv, c, x, L):
    assert 1 <= L <= c - 2
    d, q = x & 3, x >> 2
    cm = fiber(lv, c - 1, q)
    if L == 1:
        return {sh: int(fiber(lv, c - 2, sh >> 2) != 15) for sh in lv[c-1]
                if sh & 3 == d and not (cm & ~fiber(lv, c - 2, sh >> 2))}
    lo = belief_rec(lv, c - 1, q, L - 1)
    out = {}
    for sq, lc in lo.items():
        sh = 4 * sq + d
        if sh not in lv[c - 1]:
            continue
        sm = fiber(lv, c - 2, sq)
        if cm & ~sm:
            continue
        out[sh] = lc + int(sm != 15)
    return out
TEN_COUNT_CASES = [
    {"phase": "p", "h": 6, "D": 1, "q": 0xc82, "d": 0, "x": 0x3208,
     "E": [2, 0, 0, 0, 1], "O": [0, 0, 0, 0, 0],
     "cE": [0, 0, 1, 0, 0], "cO": [0, 0, 0, 0, 0]},
    {"phase": "p", "h": 6, "D": 1, "q": 0xc88, "d": 0, "x": 0x3220,
     "E": [2, 0, 0, 0, 1], "O": [0, 0, 0, 0, 0],
     "cE": [0, 0, 0, 0, 1], "cO": [0, 0, 0, 0, 0]},
]
def verify_ten_count_cases(levels):
    out = []
    for tc in TEN_COUNT_CASES:
        ph, h, D, q, x = tc["phase"], tc["h"], tc["D"], tc["q"], tc["x"]
        assert q in levels[ph][h] and x in levels[ph][h + 1]
        pb = belief(levels[ph], h, q, D)
        cb = belief(levels[ph], h + 1, x, D + 1)
        assert pb == belief_rec(levels[ph], h, q, D)
        assert cb == belief_rec(levels[ph], h + 1, x, D + 1)
        E = [0] * 5
        O = [0] * 5
        for y, c in pb.items():
            (E if c % 2 == 0 else O)[MASKS.index(fiber(levels[ph], h - 1, y))] += 1
        cE = [0] * 5
        cO = [0] * 5
        for y, c in cb.items():
            (cE if c % 2 == 0 else cO)[MASKS.index(fiber(levels[ph], h, y))] += 1
        assert E == tc["E"] and O == tc["O"], hex(q)
        assert cE == tc["cE"] and cO == tc["cO"], hex(x)
        out.append({"q_hex": hex(q), "x_hex": hex(x), "parent_E": E,
         "parent_O": O, "child_E": cE, "child_O": cO, "match": True})
    return out
def v2(x):
    return None if x == 0 else (x & -x).bit_length() - 1
class Found(Exception):
    pass
def gate_arith_selftest():
    cases = [((2, 1, True)), ((1, 1, False)), ((1, 3, True)), ((3, 5, True)), ((1, 5, False)), ((1, 0, True)), ((0, 0, False))]
    for E, O, want in cases:
        got = gate(E + O, O)
        assert got == want, (E, O, got, want)
    return len(cases)
def gate(N, O):
    a, b = v2(N), v2(2 * O)
    if a is None or b is None:
        return (a is None) != (b is None)
    return a != b
def main():
    t0 = time.monotonic()
    try:
        resource.setrlimit(resource.RLIMIT_AS, (1 << 30, resource.getrlimit(resource.RLIMIT_AS)[1]))
        rlimit = True
    except Exception:
        rlimit = False
    narith = gate_arith_selftest()
    lv = {ph: build(ph, 10, children) for ph in PHASES}
    oc = {ph: build(ph, 8, oracle_children) for ph in PHASES}
    for ph in PHASES:
        for k in range(1, 9):
            assert oc[ph][k] == lv[ph][k], (ph, k)
    checked = rec_checks = ident = 0
    ten_cases = verify_ten_count_cases(lv)
    witness = None
    for h in range(3, 10):
        for ph in PHASES:
            for D in range(1, h - 1):
                for q in sorted(lv[ph][h]):
                    for d in range(4):
                        x = 4 * q + d
                        if x not in lv[ph][h + 1]:
                            continue
                        if time.monotonic() - t0 > TIME_BUDGET:
                            raise RuntimeError("time budget exceeded")
                        pb = belief(lv[ph], h, q, D)
                        assert pb == belief_rec(lv[ph], h, q, D)
                        rec_checks += 1
                        E = {n: 0 for n in MASKS}
                        O = {n: 0 for n in MASKS}
                        for p_, c_ in pb.items():
                            n_ = fiber(lv[ph], h - 1, p_)
                            if c_ % 2 == 0:
                                E[n_] += 1
                            else:
                                O[n_] += 1
                        m = fiber(lv[ph], h, q)
                        assert (m >> d) & 1
                        A = [n for n in MASKS if not (m & ~n)]
                        Ep = E[15] + sum(O[n] for n in A if n != 15)
                        Op = O[15] + sum(E[n] for n in A if n != 15)
                        cb = belief(lv[ph], h + 1, x, D + 1)
                        assert cb == belief_rec(lv[ph], h + 1, x, D + 1)
                        rec_checks += 1
                        e2 = sum(1 for c_ in cb.values() if c_ % 2 == 0)
                        o2 = sum(1 for c_ in cb.values() if c_ % 2 == 1)
                        assert (Ep, Op) == (e2, o2), (ph, h, D, hex(q), d)
                        ident += 1
                        checked += 1
                        Nt_p, Ot_p = sum(E.values()) + sum(O.values()), sum(O.values())
                        if not gate(Nt_p, Ot_p):
                            continue
                        Nt_c = e2 + o2
                        if Nt_c == 0:
                            continue
                        if not gate(Nt_c, o2):
                            witness = {"phase": ph, "h": h, "D": D,
                             "q_hex": hex(q), "d": d, "x_hex": hex(x),
                             "m": format(m, "04b"),
                             "parent_E": [E[n] for n in MASKS],
                             "parent_O": [O[n] for n in MASKS],
                             "parent_gate": [v2(Nt_p), v2(2 * Ot_p)],
                             "parent_endpoints": sorted([[hex(y), c, format(fiber(lv[ph], h - 1, y), "04b")] for y, c in pb.items()]),
                             "child_E": e2, "child_O": o2,
                             "child_S": e2 - o2,
                             "child_gate": [v2(Nt_c), v2(2 * o2)],
                             "child_N_total": Nt_c,
                             "child_endpoints": sorted([[hex(y), c, format(fiber(lv[ph], h, y), "04b")] for y, c in cb.items()])}
                            witness["_result"] = {"transitions_checked": checked, "recursive_checks": rec_checks, "identity_checks": ident, "arith_selftest": narith, "ten_count_cases": ten_cases}
                            witness["_rlimit"] = rlimit
                            witness["_t0"] = t0
                            raise Found(witness)
    result = {"transitions_checked": checked, "recursive_checks": rec_checks,
     "identity_checks": ident, "arith_selftest": narith, "ten_count_cases": ten_cases, "witness": None, "stopped_early": False}
    return t0, rlimit, result
def payload_from(t0, rlimit, result):
    runtime = time.monotonic() - t0
    src = open("/tmp/count_transfer.py").read()
    canon = json.dumps(result, sort_keys=True).encode()
    try:
        commit = subprocess.run(["git", "-C", "/home/ryan/rule30-lab", "rev-parse", "HEAD"], capture_output=True, text=True, timeout=30).stdout.strip()
    except Exception:
        commit = "unavailable"
    model = None
    try:
        with open("/proc/cpuinfo") as fh:
            for line in fh:
                if line.startswith("model name"):
                    model = line.split(":", 1)[1].strip()
                    break
    except OSError:
        pass
    wit = result.get("witness")
    summary = {"transitions_checked": result.get("transitions_checked"),
     "identity_checks": result.get("identity_checks"),
     "counterexample_found": wit is not None,
     "stopped_early": result.get("stopped_early", False)}
    return {"experiment_id": "count-transfer-valuation-gate",
     "timestamp_utc": datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
     "git_commit": commit, "question": "problem1",
     "hypothesis": "Universal one-lift preservation of v2(N)!=v2(2O), N total endpoints, O odd-defect endpoints, on ordinary cylinders h=3..9.",
     "backend": "python-direct-and-recursive",
     "parameters": {"h_range": [3, 9], "depth": "1..h-2",
      "order": "h, phase p-u, D, q, d", "stop": "first parent-pass child-fail nonempty child",
      "time_budget_seconds": 120.0, "memory_budget_bytes": 1073741824,
      "child_nonempty_required": True, "zero_O_allowed": True},
     "hardware": {"cpu_model": model, "cpu_count": os.cpu_count(), "arch": platform.machine()},
     "software": {"python": platform.python_version(), "os": platform.platform()},
     "runtime_seconds": runtime, "rlimit_applied": rlimit,
     "result": result, "result_summary": summary,
     "result_hashes": {"certificate_sha256": hashlib.sha256(canon).hexdigest(),
      "source_sha256": hashlib.sha256(src.encode()).hexdigest()},
     "status": "refuted" if wit else "finite-exhaustive",
     "interpretation": ("A recorded parent-pass child-fail pair refutes unrestricted one-lift preservation of the valuation gate; it does not refute the restricted admissible-ancestor conjecture. No hit is finite evidence only."),
     "proof_scope": "ordinary cylinders h=3..9, depths 1..h-2, both phases; no admissible-ancestor claim.",
     "limitations": ["finite box only; no infinite conclusion",
      "single local process with 120s cooperative budget and 1GiB address cap",
      "v2(0) treated as infinite; O=0 passes nonvacuously by stated convention"],
     "source": src}

def write_payload(payload):
    data = json.dumps(payload, indent=2, sort_keys=True).encode()
    with tempfile.NamedTemporaryFile(dir="/tmp", delete=False) as fh:
        fh.write(data)
        fh.flush()
        os.fsync(fh.fileno())
        tmp = fh.name
    os.replace(tmp, OUT)
def run():
    try:
        t0, rlimit, result = main()
    except Found as f:
        w = f.args[0]
        t0 = time.monotonic()
        result = w.get("_result", {})
        keep = {}
        for kk, vv in w.items():
            if kk[0:1] != "_":
                keep[kk] = vv
        result["witness"] = keep
        result["stopped_early"] = True
        rlimit = w.get("_rlimit", False)
        t0 = w.get("_t0", t0)
    payload = payload_from(t0, rlimit, result)
    write_payload(payload)
    print(json.dumps({"status": payload["status"], "checked": result.get("transitions_checked"), "witness": result.get("witness")}, indent=1))
run()
